/**
 * Builds dist/atlas-inline-bundle.js — everything index.html needs inlined
 * into its own <script> block to generate the Executive Brief on the fly,
 * with NO second .html file involved. This is the production integration
 * path (see README.md > "No separate file: generating the Brief inline").
 *
 * What's inside, and why each piece is there:
 *   - data/*.json, i18n/*.json           → the knowledge base (unchanged by scope)
 *   - src/report-engine.js               → computes a model from the Atlas's
 *                                           CURRENT license selection, in the
 *                                           parent page (index.html) itself
 *   - src/i18n.js + src/render-report.js → rendering only; also re-inlined a
 *                                           second time INSIDE each generated
 *                                           popup by render-brief-document.js,
 *                                           since the popup is a separate
 *                                           document with no access to the
 *                                           parent's JS scope
 *   - src/render-brief-document.js       → turns a computed model into a full
 *                                           HTML string and opens it
 *   - theme/report-light.css             → inlined as a JS string constant,
 *                                           passed through to each popup
 *
 * The output is a single JS file: paste its contents into index.html's
 * existing <script> block (anywhere; order doesn't matter relative to the
 * Atlas's own code, as long as it's before openExecutiveBrief() can be
 * called). Then wire the button per integration/atlas-handoff-snippet.html.
 */
const fs = require("fs");
const path = require("path");

const ROOT = path.join(__dirname, "..");
const read = (p) => fs.readFileSync(path.join(ROOT, p), "utf8");
const readJSON = (p) => JSON.parse(read(p));

const sourcesData = readJSON("data/sources.example.json");
const licenseCatalog = readJSON("data/licenses.json");
const mitreData = readJSON("data/mitre-mapping.json");
const tacticGroups = readJSON("data/tactic-groups.json");
const riskNarratives = readJSON("data/risk-narratives.json");
const productsCatalog = readJSON("data/products.json");
const ransomwareChain = readJSON("data/ransomware-chain.json");
const en = readJSON("i18n/en.json");
const fr = readJSON("i18n/fr.json");
const theme = read("theme/report-light.css");

const rendererOnlySrc = read("src/i18n.js") + "\n" + read("src/render-report.js");
const parentRunningSrc = read("src/report-engine.js") + "\n" + read("src/render-brief-document.js");

const bundle = `/* ============================================================
   Microsoft Defensive Cloud Atlas — Executive Brief inline bundle
   Generated by build/build-atlas-bundle.js — do not hand-edit.
   Paste this whole block into index.html's <script> section.
   ============================================================ */
const ATLAS_BRIEF_SOURCES = ${JSON.stringify(sourcesData.sources)};
const ATLAS_BRIEF_LICENSES = ${JSON.stringify(licenseCatalog)};
const ATLAS_BRIEF_MITRE = ${JSON.stringify(mitreData)};
const ATLAS_BRIEF_TACTIC_GROUPS = ${JSON.stringify(tacticGroups)};
const ATLAS_BRIEF_RISK_NARRATIVES = ${JSON.stringify(riskNarratives)};
const ATLAS_BRIEF_PRODUCTS = ${JSON.stringify(productsCatalog)};
const ATLAS_BRIEF_RANSOMWARE_CHAIN = ${JSON.stringify(ransomwareChain)};
const ATLAS_BRIEF_I18N = { en: ${JSON.stringify(en)}, fr: ${JSON.stringify(fr)} };
const ATLAS_BRIEF_THEME_CSS = ${JSON.stringify(theme)};
// Embedded as TEXT, not executed here — this is what gets inlined INSIDE
// each generated popup document, which has no access to this page's JS
// scope. Runs in the parent too: report-engine.js and render-brief-document.js
// below are the only pieces that actually execute in index.html itself.
const ATLAS_BRIEF_RENDERER_SRC = ${JSON.stringify(rendererOnlySrc)};

${parentRunningSrc}

function labelForLicenseIds(ids, lang) {
  return ids.map((id) => {
    const l = ATLAS_BRIEF_LICENSES.licenses.find((x) => x.id === id);
    return l ? l.name[lang] : id;
  }).join(" + ");
}

/**
 * Call this from the Atlas's "Executive Brief" button. selectedLicenseIds
 * should be whatever the license panel currently tracks as selected — the
 * ids the user clicked, not the already-expanded "included" set;
 * AtlasReportEngine resolves bundle inclusion itself.
 */
function openExecutiveBrief(selectedLicenseIds, lang) {
  if (!selectedLicenseIds || !selectedLicenseIds.length) return;
  const model = AtlasReportEngine.buildReportModel({
    sources: ATLAS_BRIEF_SOURCES,
    licenseCatalog: ATLAS_BRIEF_LICENSES,
    mitreData: ATLAS_BRIEF_MITRE,
    tacticGroups: ATLAS_BRIEF_TACTIC_GROUPS,
    riskNarratives: ATLAS_BRIEF_RISK_NARRATIVES,
    productsCatalog: ATLAS_BRIEF_PRODUCTS,
    ransomwareChain: ATLAS_BRIEF_RANSOMWARE_CHAIN,
    selectedLicenseIds: selectedLicenseIds,
  });
  const scopeLabels = { en: labelForLicenseIds(selectedLicenseIds, "en"), fr: labelForLicenseIds(selectedLicenseIds, "fr") };
  const html = AtlasBriefDocument.buildBriefDocument({
    model: model,
    initialLang: lang || "en",
    i18nCatalogs: ATLAS_BRIEF_I18N,
    scopeLabels: scopeLabels,
    themeCss: ATLAS_BRIEF_THEME_CSS,
    rendererSrc: ATLAS_BRIEF_RENDERER_SRC,
  });
  AtlasBriefDocument.openBriefDocument(html);
}
`;

const outPath = path.join(ROOT, "dist", "atlas-inline-bundle.js");
fs.mkdirSync(path.dirname(outPath), { recursive: true });
fs.writeFileSync(outPath, bundle);
console.log("Wrote", outPath, "(", bundle.length, "bytes )");
